import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = 1;
        long MOD = 1000000007;

        for (int t = 0; t < T; t++) {
            int total = scanner.nextInt();
            int factor = scanner.nextInt();

            int[] sequence = new int[total];
            for (int i = 0; i < total; i++) {
                sequence[i] = (factor * i) % total;
            }

            if (factor == 0) {
                System.out.println(powMod(total, total - 1, MOD));
                continue;
            }

            boolean[] visited = new boolean[total];
            int[] cycleCounts = new int[total + 1]; // size up to total
            long result = 1;

            for (int startPoint = 0; startPoint < total; startPoint++) {
                if (visited[startPoint]) {
                    continue;
                }
                int length = 0;
                int currentNode = startPoint;
                while (!visited[currentNode]) {
                    visited[currentNode] = true;
                    currentNode = sequence[currentNode];
                    length++;
                }
                cycleCounts[length]++;
            }

            for (int size = 1; size < total; size++) {
                int c = cycleCounts[size];
                if (c != 0) {
                    long totalValue = size * c + (size > 1 ? 1 : 0);
                    result = (result * powMod(totalValue, c, MOD)) % MOD;
                }
            }

            System.out.println(result);
        }
        scanner.close();
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1;
        long currentPower = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * currentPower) % mod;
            }
            currentPower = (currentPower * currentPower) % mod;
            exp >>= 1;
        }
        return result;
    }
}
